target.css:
:root {
  --cream: #f5eedc;
  --brown-dark: #3b2a1a;
  --brown-mid: #7a5230;
  --brown-light: #c49a6c;
  --blue-wing: #2e6ea6;
  --blue-wing-light: #5aa3d0;
  --blue-wing-dark: #1a3f5e;
  --amber: #d4882a;
  --green-status: #3a6b3a;
  --border-rule: #b08050;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.specimen-card {
  background-color: var(--cream);
  border: 2px solid var(--brown-mid);
  border-radius: 4px;
  width: 480px;
  display: flex;
  flex-direction: column;
  outline: 4px double var(--border-rule);
  outline-offset: -6px;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  border-bottom: 2px solid var(--brown-mid);
  background-color: var(--brown-dark);
}

.collection-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--brown-light);
  text-transform: uppercase;
}

.specimen-number {
  font-size: 13px;
  font-weight: 700;
  color: var(--amber);
  letter-spacing: 0.05em;
}

.card-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.specimen-display {
  width: 160px;
  min-height: 200px;
  background-color: var(--cream);
  border-right: 1.5px solid var(--border-rule);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px 8px;
  margin: 0;
  gap: 2px;
}

.pin-head {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--brown-dark);
  border: 1.5px solid var(--brown-mid);
}

.pin-shaft {
  width: 2px;
  height: 18px;
  background-color: var(--brown-mid);
}

.insect {
  display: grid;
  grid-template-columns: 44px 20px 44px;
  grid-template-rows: 30px 24px 32px;
  align-items: center;
  justify-items: center;
}

.wing-left-top {
  grid-column: 1;
  grid-row: 1;
  width: 42px;
  height: 28px;
  background-color: var(--blue-wing);
  border-radius: 50% 8px 8px 40%;
  border: 1.5px solid var(--blue-wing-dark);
  opacity: 0.9;
}

.wing-left-bottom {
  grid-column: 1;
  grid-row: 2 / 4;
  width: 34px;
  height: 40px;
  background-color: var(--blue-wing-light);
  border-radius: 40% 8px 40% 50%;
  border: 1.5px solid var(--blue-wing-dark);
  opacity: 0.85;
}

.wing-right-top {
  grid-column: 3;
  grid-row: 1;
  width: 42px;
  height: 28px;
  background-color: var(--blue-wing);
  border-radius: 8px 50% 40% 8px;
  border: 1.5px solid var(--blue-wing-dark);
  opacity: 0.9;
}

.wing-right-bottom {
  grid-column: 3;
  grid-row: 2 / 4;
  width: 34px;
  height: 40px;
  background-color: var(--blue-wing-light);
  border-radius: 8px 40% 50% 40%;
  border: 1.5px solid var(--blue-wing-dark);
  opacity: 0.85;
}

.head {
  grid-column: 2;
  grid-row: 1;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--brown-dark);
}

.thorax {
  grid-column: 2;
  grid-row: 2;
  width: 10px;
  height: 18px;
  border-radius: 30%;
  background-color: var(--brown-mid);
}

.abdomen {
  grid-column: 2;
  grid-row: 3;
  width: 9px;
  height: 26px;
  border-radius: 4px 4px 50% 50%;
  background-color: var(--brown-dark);
}

.specimen-caption {
  font-size: 11px;
  font-style: italic;
  color: var(--brown-mid);
  margin-top: 8px;
  text-align: center;
}

.specimen-info {
  flex: 1;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.common-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--brown-dark);
  margin: 0;
  line-height: 1.2;
  border-bottom: 1px solid var(--border-rule);
  padding-bottom: 8px;
}

.taxonomy-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.taxonomy-list li {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  border-bottom: 1px dotted var(--border-rule);
  padding-bottom: 3px;
}

.tax-label {
  font-weight: 600;
  color: var(--brown-mid);
  text-transform: uppercase;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.tax-value {
  color: var(--brown-dark);
  font-style: italic;
}

.meta-row {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  background-color: var(--brown-dark);
  border-radius: 4px;
  padding: 5px 8px;
  flex: 1;
}

.meta-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--brown-light);
}

.meta-value {
  font-size: 11px;
  font-weight: 600;
  color: var(--cream);
}

.status {
  color: var(--amber);
  font-weight: 700;
  font-size: 13px;
}

.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 16px;
  border-top: 2px solid var(--brown-mid);
  background-color: var(--brown-dark);
}

.institution {
  font-size: 9px;
  letter-spacing: 0.08em;
  color: var(--brown-light);
  text-transform: uppercase;
}

.barcode {
  font-size: 14px;
  color: var(--amber);
  letter-spacing: 0.02em;
}

